// Safe localStorage helper with auto-pruning to prevent QuotaExceededError
export const safeLocalStorageSet = (key: string, value: string): boolean => {
  try {
    localStorage.setItem(key, value);
    return true;
  } catch (e: any) {
    console.warn(`[SafeStorage] QuotaExceeded or write error on key "${key}":`, e);
    try {
      if (key === 'src_shift_logs') {
        const parsed = JSON.parse(value);
        if (Array.isArray(parsed)) {
          const active = parsed.filter((l: any) => l && l.status === 'aktif');
          const finished = parsed.filter((l: any) => l && l.status !== 'aktif').slice(0, 15);
          localStorage.setItem(key, JSON.stringify([...active, ...finished]));
          return true;
        }
      }

      // Clear non-vital caches
      const nonEssentialKeys = [
        'src_temp_preview', 
        'src_audit_cache', 
        'src_pdf_temp', 
        'src_cached_stats', 
        'src_temp_img'
      ];
      for (const k of nonEssentialKeys) {
        try { localStorage.removeItem(k); } catch (_) {}
      }

      // Compact shift logs in storage
      try {
        const storedShift = localStorage.getItem('src_shift_logs');
        if (storedShift) {
          const parsed = JSON.parse(storedShift);
          if (Array.isArray(parsed) && parsed.length > 15) {
            const active = parsed.filter((l: any) => l && l.status === 'aktif');
            const finished = parsed.filter((l: any) => l && l.status !== 'aktif').slice(0, 15);
            localStorage.setItem('src_shift_logs', JSON.stringify([...active, ...finished]));
          }
        }
      } catch (_) {}

      // Compact mutasi stok logs in storage
      try {
        const storedMutasi = localStorage.getItem('src_mutasi_stok_logs');
        if (storedMutasi) {
          const parsedM = JSON.parse(storedMutasi);
          if (Array.isArray(parsedM) && parsedM.length > 30) {
            localStorage.setItem('src_mutasi_stok_logs', JSON.stringify(parsedM.slice(0, 30)));
          }
        }
      } catch (_) {}

      localStorage.setItem(key, value);
      return true;
    } catch (retryErr) {
      console.error(`[SafeStorage] Failed to persist key "${key}" after cleanup:`, retryErr);
      return false;
    }
  }
};

