  const [pelangganFormCatatan, setPelangganFormCatatan] = useState('');
  const [pelangganFormBolehHutangRokok, setPelangganFormBolehHutangRokok] = useState<boolean>(false);
  const [pelangganFormLimitKredit, setPelangganFormLimitKredit] = useState<string>('500000');
  const [cariPelangganText, setCariPelangganText] = useState('');
  const [memberSortKey, setMemberSortKey] = useState<'id-asc' | 'nama-asc' | 'nama-desc' | 'poin-desc' | 'belanja-desc' | 'tanggal-desc'>('id-asc');

  // --- STATE CATATAN BUKU HUTANG ---
  const [cariUtangText, setCariUtangText] = useState('');
