  const [tempMinBelanja, setTempMinBelanja] = useState<number>(minBelanjaPerPoin);
  const [tempNilaiRupiahPerPoin, setTempNilaiRupiahPerPoin] = useState<number>(nilaiRupiahPerPoin);

