  const handleParkCart = (customLabel?: string) => {
    const cartItems = getCartDetails();
    if (cartItems.length === 0) {
      showToast("⚠️ Keranjang belanjaan masih kosong!");
      return;
    }
    
    const timeStr = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
    const count = parkedCarts.length + 1;
    const finalLabel = customLabel?.trim() || `Transaksi Pending ${count} (${timeStr})`;
    
    const newParked = {
      id: `PARK-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
      label: finalLabel,
      keranjang: { ...keranjangRef.current },
      selectedPelangganId: selectedPelanggan ? selectedPelanggan.id : null,
      poinYangDitukar,
      metodePembayaran,
      uangBayar,
      timestamp: Date.now(),
      virtualItems: { ...virtualItems }
    };

    const nextCarts = [newParked, ...parkedCarts];
    saveParkedCarts(nextCarts);
    
    // Reset active cart states
    setKeranjang({});
    setSelectedPelanggan(null);
    setPoinYangDitukar(0);
    setMetodePembayaran('Tunai');
    setUangBayar('');
    
    showToast(`📌 Keranjang berhasil digantung: "${finalLabel}"`);
  };

  const handleRestoreParkedCart = (id: string) => {
    const target = parkedCarts.find(c => c.id === id);
    if (!target) return;

    // Check if active cart is not empty and ask user's decision
    if (Object.keys(keranjangRef.current).length > 0) {
      showCustomConfirm("Rincian keranjang aktif tidak kosong. Apakah Anda ingin MENGGABUNGKAN keranjang aktif dengan keranjang pending ini?\n\n- OK / YES: Gabungkan\n- BATAL / CANCEL: Tulis Ulang (Ganti Baru)").then((confirmGabung) => {
        if (confirmGabung) {
          // Merge
          const mergedCart = { ...keranjangRef.current };
          Object.entries(target.keranjang).forEach(([itemId, qty]) => {
            mergedCart[itemId] = (mergedCart[itemId] || 0) + qty;
          });
          setKeranjang(mergedCart);
          showToast(`⚡ Keranjang berhasil digabungkan dengan ${target.label}!`);
        } else {
          // Overwrite
          setKeranjang(target.keranjang);
          if (target.selectedPelangganId) {
            const foundUser = pelanggan.find(p => p.id === target.selectedPelangganId);
            if (foundUser) {
              setSelectedPelanggan(foundUser);
            }
          } else {
            setSelectedPelanggan(null);
          }
          setPoinYangDitukar(target.poinYangDitukar || 0);
          setMetodePembayaran(target.metodePembayaran || 'Tunai');
          setUangBayar(target.uangBayar || '');
          if (target.virtualItems) {
            setVirtualItems(prev => ({ ...prev, ...target.virtualItems }));
          }
          showToast(`⚡ Keranjang pending "${target.label}" berhasil dipulihkan!`);
        }
        
        // Remove restored item from parked carts
        const filtered = parkedCarts.filter(c => c.id !== id);
        saveParkedCarts(filtered);
      });
    } else {
      // Active cart is empty, simple replace
      setKeranjang(target.keranjang);
      if (target.selectedPelangganId) {
        const foundUser = pelanggan.find(p => p.id === target.selectedPelangganId);
        if (foundUser) {
          setSelectedPelanggan(foundUser);
        }
      } else {
        setSelectedPelanggan(null);
      }
      setPoinYangDitukar(target.poinYangDitukar || 0);
      setMetodePembayaran(target.metodePembayaran || 'Tunai');
      setUangBayar(target.uangBayar || '');
      if (target.virtualItems) {
        setVirtualItems(prev => ({ ...prev, ...target.virtualItems }));
      }
      
      const filtered = parkedCarts.filter(c => c.id !== id);
      saveParkedCarts(filtered);
      showToast(`⚡ Keranjang pending "${target.label}" berhasil dipulihkan!`);
    }
  };

