  // Auto shift log synchronization when active cashier changes
  useEffect(() => {
    if (!config.kasirAktif) return;
    const now = new Date();
    const formatTimestamp = (d: Date) => {
      const pad = (num: number) => String(num).padStart(2, '0');
      return `${pad(d.getDate())}-${pad(d.getMonth() + 1)}-${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
    };
    const formattedNow = formatTimestamp(now);
    const nowMs = now.getTime();

    setShiftLogs(prevLogs => {
      const safeLogs = Array.isArray(prevLogs) ? prevLogs : [];
      const activeShift = safeLogs.find(log => log.status === 'aktif');
      if (activeShift && activeShift.namaKasir === config.kasirAktif) {
        return safeLogs;
      }

      // Complete previous active shift if cashier changed
      const updated = safeLogs.map(log => {
        if (log.status === 'aktif') {
          return { ...log, selesai: formattedNow, selesaiMs: nowMs, status: 'selesai' as const };
        }
        return log;
      });

      // Start new active shift for config.kasirAktif
      const newShift: ShiftLog = {
        id: 'SHIFT-' + Math.random().toString(36).substring(2, 11).toUpperCase(),
        namaKasir: config.kasirAktif,
        mulai: formattedNow,
        mulaiMs: nowMs,
        status: 'aktif'
      };
      const finalLogs = [newShift, ...updated].slice(0, 30);
      safeLocalStorageSet('src_shift_logs', JSON.stringify(finalLogs));
      return finalLogs;
    });
  }, [config.kasirAktif]);

  // Shift Automation and Warning Scheduler Effect
  useEffect(() => {
    const getMinutesFromTimeStr = (timeStr: string): number => {
      if (!timeStr || !timeStr.includes(':')) return 0;
      const [h, m] = timeStr.split(':').map(Number);
      return (h || 0) * 60 + (m || 0);
    };

    const checkShiftTime = () => {
      const now = new Date();
      const currentHour = now.getHours();
      const currentMinute = now.getMinutes();
      const currentMinFromMidnight = currentHour * 60 + currentMinute;

      if (currentMinFromMidnight === lastProcessedShiftMinute) {
        return;
      }

      const formatTimestamp = (d: Date) => {
        const pad = (num: number) => String(num).padStart(2, '0');
        return `${pad(d.getDate())}-${pad(d.getMonth() + 1)}-${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
      };

      const pagiMulaiMin = getMinutesFromTimeStr(shiftSchedule.pagiMulai);
      const pagiSelesaiMin = getMinutesFromTimeStr(shiftSchedule.pagiSelesai);
      const soreMulaiMin = getMinutesFromTimeStr(shiftSchedule.soreMulai);
      const soreSelesaiMin = getMinutesFromTimeStr(shiftSchedule.soreSelesai);

      // 15-minute warning check
      const isPagiWarning = currentMinFromMidnight === pagiSelesaiMin - 15;
      const isSoreWarning = currentMinFromMidnight === soreSelesaiMin - 15;

      if (isPagiWarning) {
        setShiftWarningMsg(`⚠️ Peringatan: Shift Pagi (${shiftSchedule.pagiMulai} - ${shiftSchedule.pagiSelesai}) akan berakhir dalam 15 menit (Pukul ${shiftSchedule.pagiSelesai}). Mohon segera proses transaksi berjalan dan bersiap melakukan pelunasan shift.`);
        showToast(`⏰ Peringatan: 15 menit sebelum Shift Pagi berakhir!`);
      } else if (isSoreWarning) {
        setShiftWarningMsg(`⚠️ Peringatan: Shift Sore (${shiftSchedule.soreMulai} - ${shiftSchedule.soreSelesai}) akan berakhir dalam 15 menit (Pukul ${shiftSchedule.soreSelesai}). Mohon segera proses transaksi berjalan dan bersiap melakukan pelunasan shift.`);
        showToast(`⏰ Peringatan: 15 menit sebelum Shift Sore berakhir!`);
      } else {
        // Clear warning outside of warning minutes
        const isStillInPagiWarningZone = currentMinFromMidnight >= pagiSelesaiMin - 15 && currentMinFromMidnight < pagiSelesaiMin;
        const isStillInSoreWarningZone = currentMinFromMidnight >= soreSelesaiMin - 15 && currentMinFromMidnight < soreSelesaiMin;
        if (!isStillInPagiWarningZone && !isStillInSoreWarningZone) {
          setShiftWarningMsg(null);
        }
      }

      // Exact transition checks
      const activeShift = shiftLogs.find(log => log.status === 'aktif');

      // 1. Shift Pagi ends (e.g. 14:00)
      if (currentMinFromMidnight === pagiSelesaiMin) {
        setLastProcessedShiftMinute(currentMinFromMidnight);
        setShiftWarningMsg(null);
        if (activeShift) {
          if (shiftSchedule.autoAkhiriShift !== false) {
            localStorage.removeItem('src_kasir_aktif');
            handleConfigUpdate('kasirAktif', '');
            const formattedNow = formatTimestamp(now);
            const nowMs = now.getTime();
            const updated = shiftLogs.map(log => {
              if (log.id === activeShift.id) {
                return { ...log, selesai: formattedNow, selesaiMs: nowMs, status: 'selesai' as const };
              }
              return log;
            });
            const compacted = updated.slice(0, 30);
            setShiftLogs(compacted);
            safeLocalStorageSet('src_shift_logs', JSON.stringify(compacted));
            showToast(`🕒 Shift Pagi berakhir! Shift "${activeShift.namaKasir}" telah diakhiri otomatis.`);
            showCustomAlert(`🕒 Waktu Shift Pagi telah habis (Pukul ${shiftSchedule.pagiSelesai}). Shift "${activeShift.namaKasir}" telah otomatis ditutup sesuai jadwal.\n\nSilakan mulai Shift Sore untuk kasir berikutnya.`, "PERGANTIAN SHIFT OTOMATIS");
          } else {
            showToast(`⏰ Jam kerja Shift Pagi selesai (${shiftSchedule.pagiSelesai}). Akhiri shift manual.`);
            setShiftWarningMsg(`⏰ Waktu Shift Pagi telah berakhir (Pukul ${shiftSchedule.pagiSelesai}). Silakan akhiri shift kasir secara manual.`);
          }
        }
      }

      // 2. Shift Sore ends (e.g. 21:00)
      if (currentMinFromMidnight === soreSelesaiMin) {
        setLastProcessedShiftMinute(currentMinFromMidnight);
        setShiftWarningMsg(null);
        if (activeShift) {
          if (shiftSchedule.autoAkhiriShift !== false) {
            localStorage.removeItem('src_kasir_aktif');
            handleConfigUpdate('kasirAktif', '');
            const formattedNow = formatTimestamp(now);
            const nowMs = now.getTime();
            const updated = shiftLogs.map(log => {
              if (log.id === activeShift.id) {
                return { ...log, selesai: formattedNow, selesaiMs: nowMs, status: 'selesai' as const };
              }
              return log;
            });
            const compacted = updated.slice(0, 30);
            setShiftLogs(compacted);
            safeLocalStorageSet('src_shift_logs', JSON.stringify(compacted));
            showToast(`🕒 Shift Sore berakhir! Shift "${activeShift.namaKasir}" telah diakhiri otomatis.`);
            showCustomAlert(`🕒 Waktu Shift Sore telah habis (Pukul ${shiftSchedule.soreSelesai}). Shift "${activeShift.namaKasir}" telah otomatis ditutup sesuai jadwal.\n\nSilakan bersiap untuk memulai operasional hari berikutnya.`, "PERGANTIAN SHIFT OTOMATIS");
          } else {
            showToast(`⏰ Jam kerja Shift Sore selesai (${shiftSchedule.soreSelesai}). Akhiri shift manual.`);
            setShiftWarningMsg(`⏰ Waktu Shift Sore telah berakhir (Pukul ${shiftSchedule.soreSelesai}). Silakan akhiri shift kasir secara manual.`);
          }
        }
      }
    };

    checkShiftTime();
    const timerId = setInterval(checkShiftTime, 10000);
    return () => clearInterval(timerId);
  }, [shiftLogs, shiftSchedule, lastProcessedShiftMinute]);

