  // Screen Orientation Detection (Portrait vs Landscape)
  // Protected against soft keyboard popup resize by checking physical hardware sensors first
  const detectHardwareOrientation = (): 'portrait' | 'landscape' => {
    if (typeof window === 'undefined') return 'portrait';
    // 1. Physical sensor API (Supported on Android & iOS WebView)
    if (window.screen?.orientation?.type) {
      return window.screen.orientation.type.startsWith('landscape') ? 'landscape' : 'portrait';
    }
    // 2. Legacy window.orientation (0/180 = portrait, 90/-90 = landscape)
    if (typeof window.orientation === 'number') {
      return Math.abs(window.orientation) === 90 ? 'landscape' : 'portrait';
    }
    // 3. Desktop / large displays (min width 1024px and width > height)
    if (window.innerWidth >= 1024 && window.innerWidth > window.innerHeight) {
      return 'landscape';
    }
    // 4. Physical screen dimensions fallback (unaffected by software keyboard)
    if (window.screen?.width && window.screen?.height) {
      return window.screen.width > window.screen.height ? 'landscape' : 'portrait';
    }
    return 'portrait';
  };

  const [deviceOrientation, setDeviceOrientation] = useState<'portrait' | 'landscape'>(detectHardwareOrientation);

  // Responsive Orientation Event Listener (Listens to physical rotation, immune to keyboard popup)
  useEffect(() => {
    const updateOrientation = () => {
      setDeviceOrientation(detectHardwareOrientation());
    };

    updateOrientation();

    // Listen to physical device orientation changes
    window.addEventListener('orientationchange', updateOrientation);
    if (typeof window !== 'undefined' && window.screen && window.screen.orientation) {
      try {
        window.screen.orientation.addEventListener('change', updateOrientation);
      } catch (e) {}
    }

    const handleVisibility = () => {
      if (document.visibilityState === 'visible') {
        updateOrientation();
      }
    };

    document.addEventListener('visibilitychange', handleVisibility);

    return () => {
      window.removeEventListener('orientationchange', updateOrientation);
      if (typeof window !== 'undefined' && window.screen && window.screen.orientation) {
        try {
          window.screen.orientation.removeEventListener('change', updateOrientation);
        } catch (e) {}
      }
      document.removeEventListener('visibilitychange', handleVisibility);
    };
  }, []);

