    setFormG2Min(item.g2Min || '');
    setFormG2Harga(item.g2Harga || '');
    setFormExpired(item.expired || '');
    setFormKategori(item.kategori || 'Lain-lain');
    setFormMinStok(item.minStok !== undefined ? item.minStok : '');
