  const deleteProduct = async (id: string, nama: string) => {
    const setujuHapus = await showCustomConfirm(`Hapus produk "${nama}" dari stok toko?`);
    if (setujuHapus) {
      const oldItem = barang.find(p => p.id === id);
      const oldStok = oldItem ? oldItem.stok : 0;
      registerDeletions('barang', [id]);
      const filtered = barang.filter(p => p.id !== id);
      saveBarang(filtered);
      addMutasiLog(
        id,
        nama,
        'hapus',
        oldStok,
        0,
        -oldStok,
        `Produk dihapus dari sistem`
      );
      showToast(`Hapus item "${nama}".`);
    }
  };

  const saveCustomCategories = (nextCats: string[]) => {
    setCustomCategories(nextCats);
    localStorage.setItem('src_custom_categories', JSON.stringify(nextCats));
  };

  const handleAddNewCategory = (catName: string): boolean => {
    const trimmed = catName.trim();
    if (!trimmed) {
      showToast('⚠️ Nama kategori tidak boleh kosong');
      return false;
    }
    if (customCategories.includes(trimmed)) {
      showToast('⚠️ Kategori sudah ada');
      return false;
    }
    const updated = [...customCategories, trimmed];
    saveCustomCategories(updated);
    showToast(`✨ Kategori "${trimmed}" berhasil dibuat!`);
    return true;
  };

  const handleDeleteCategory = async (catToDelete: string) => {
    const setuju = await showCustomConfirm(`Apakah Anda yakin ingin menghapus kategori "${catToDelete}"? Semua barang dengan kategori ini akan secara otomatis dialihkan ke "Lain-lain" agar tidak kehilangan data.`);
    if (setuju) {
      const updated = customCategories.filter(c => c !== catToDelete);
      saveCustomCategories(updated);
      
      // update existing items
      const updatedBarang = barang.map(item => {
        if (item.kategori === catToDelete) {
          return { ...item, kategori: 'Lain-lain' };
        }
        return item;
      });
      saveBarang(updatedBarang);
      
      // adjust filter if current filter was deleted
      if (filterKategoriGudang === catToDelete) {
        setFilterKategoriGudang('Semua');
      }
      
      showToast(`🗑️ Kategori "${catToDelete}" dihapus & barang dialihkan ke Lain-lain`);
    }
  };

  const resetProductForm = () => {
    setFormId('');
    setFormNama('');
    setFormKode('');
    setFormFoto('');
    setFormBeli('');
    setFormJual('');
    setFormStok('');
    setFormG1Min('');
    setFormG1Harga('');
    setFormG2Min('');
    setFormG2Harga('');
    setFormExpired('');
    setFormKategori('Lain-lain');
    setFormMinStok('');
    setFormRak('');
    setFormSupplier('');
    setFormDuplikasiError('');

    // Clear multi-satuan configurations and inputs
    setFormMultiSatuan([]);
    setIsMultiSatuanCollapsed(true);
    setNewSatuanNama('Renceng');
    setNewSatuanCustomName('');
    setNewSatuanIsi('');
    setNewSatuanHarga('');
    setNewSatuanBarcode('');
  };

  const addMultiSatuanItem = () => {
    const finalNama = newSatuanNama === 'Kustom' ? newSatuanCustomName.trim() : newSatuanNama;
    const isi = Number(newSatuanIsi) || 0;
    const harga = Number(newSatuanHarga) || 0;
    const bc = newSatuanBarcode.trim();

    if (!finalNama) {
      showToast('⚠️ Nama satuan wajib diisi!');
      return;
    }
    if (isi <= 0) {
      showToast('⚠️ Jumlah konversi isi (pcs) wajib lebih dari 0!');
      return;
    }
    if (harga <= 0) {
      showToast('⚠️ Harga jual satuan wajib lebih dari 0!');
      return;
    }

    const newItem: MultiSatuanItem = {
      id: `unit-${Date.now()}`,
      namaSatuan: finalNama,
      isiPcs: isi,
      hargaJual: harga,
      barcode: bc || undefined
    };

    setFormMultiSatuan(prev => [...prev, newItem]);
    
    // Clear draft states
    setNewSatuanCustomName('');
    setNewSatuanIsi('');
    setNewSatuanHarga('');
    setNewSatuanBarcode('');
    showToast(`✅ Satuan "${finalNama}" ditambahkan ke rancangan!`);
  };

  const removeMultiSatuanItem = (id: string) => {
    setFormMultiSatuan(prev => prev.filter(item => item.id !== id));
    showToast(`🗑️ Satuan dihapus dari rancangan.`);
  };

  const handleMultiSatuanInputKeyDown = (e: React.KeyboardEvent<HTMLInputElement | HTMLSelectElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault(); // Stop main form from submitting/saving the product
      
      const finalNama = newSatuanNama === 'Kustom' ? newSatuanCustomName.trim() : newSatuanNama;
      const isi = Number(newSatuanIsi) || 0;
      const harga = Number(newSatuanHarga) || 0;
      
      if (finalNama && isi > 0 && harga > 0) {
        // Automatically trigger addition of this unit conversion
        addMultiSatuanItem();
      } else {
        showToast('⚠️ Silakan lengkapi Satuan, Isi, dan Harga Jual terlebih dahulu!');
      }
    }
  };

  const getExpirationStatus = (expiredDateStr?: string) => {
    if (!expiredDateStr) return { status: 'none', label: '-', badgeClass: 'text-slate-400 font-normal' };
    
    const today = new Date();
    const expDate = new Date(expiredDateStr);
    
    today.setHours(0,0,0,0);
    expDate.setHours(0,0,0,0);
    
    const diffTime = expDate.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    
    if (diffDays < 0) {
      return { 
        status: 'expired', 
        label: `EXPIRED (${expiredDateStr})`, 
        badgeClass: 'bg-rose-100 text-rose-700 border border-rose-300 font-bold',
        daysLeft: diffDays
      };
    } else if (diffDays <= 30) {
      return { 
        status: 'soon', 
        label: `DEKAT EXPIRED (${diffDays} hari lagi - ${expiredDateStr})`, 
        badgeClass: 'bg-amber-100 text-amber-800 border border-amber-300 font-bold animate-pulse',
        daysLeft: diffDays
      };
    } else {
      return { 
        status: 'safe', 
        label: expiredDateStr, 
        badgeClass: 'bg-slate-100 text-slate-700 font-medium',
        daysLeft: diffDays
      };
    }
  };

  const expiredOrSoonProducts = useMemo(() => {
    const today = new Date();
    today.setHours(0,0,0,0);
    const todayTime = today.getTime();
    
    return barang.filter(item => {
      if (!item.expired) return false;
      const expDate = new Date(item.expired);
      expDate.setHours(0,0,0,0);
      const diffTime = expDate.getTime() - todayTime;
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      return diffDays <= 30; // Expired or expiring within 30 days
    }).sort((a, b) => {
      const dateA = a.expired ? new Date(a.expired).getTime() : 0;
      const dateB = b.expired ? new Date(b.expired).getTime() : 0;
      return dateA - dateB;
    });
  }, [barang]);

  const handleEmptyGudang = async () => {
    const setuju = await showCustomConfirm("⚠️ PERINGATAN KERAS: Anda akan mengosongkan seluruh stok toko! Aksi ini tidak dapat dibatalkan. Lanjutkan?");
    if (setuju) {
      saveBarang([]);
      setKeranjang({});
      showToast("Stok toko dikosongkan.");
    }
  };

  const handleSetAllStocksTo999 = async () => {
    const setuju = await showCustomConfirm("⚠️ Apakah Anda yakin ingin mengatur jumlah semua stok barang di toko menjadi 999 unit?");
    if (setuju) {
      const updated = barang.map(p => ({
        ...p,
        stok: 999
      }));
      saveBarang(updated);
      showToast("✨ Seluruh stok barang berhasil diatur menjadi 999 unit!");
    }
  };

  const handleResetDefaultData = async () => {
    const setuju = await showCustomConfirm("⚠️ Apakah Anda yakin ingin mengembalikan seluruh database ke daftar barang default (berisi produk dari susunan CSV baru Anda seperti 76 Apel, 76 Kretek, dsb)? Tindakan ini akan menimpa stok lama Anda saat ini.");
    if (setuju) {
      saveBarang(INITIAL_BARANG);
      setKeranjang({});
      showToast("Katalog berhasil disesuaikan dengan daftar CSV baru!");
    }
  };

  const handleInstallPWA = async () => {
    if (deferredPrompt) {
      try {
        deferredPrompt.prompt();
        const { outcome } = await deferredPrompt.userChoice;
        if (outcome === 'accepted') {
          showToast("Terima kasih sudah memasang SRC MASNGUD! 🎉");
          setDeferredPrompt(null);
        }
      } catch (err) {
        setShowAndroidGuide(true);
      }
    } else {
      setShowAndroidGuide(true);
    }
  };

  // --- EXPORT / IMPORT MASS TRANSFERS OUT OF CSV ---
  const handleExportCSV = async () => {
    if (barang.length === 0) {
      await showCustomAlert("Katalog Anda kosong. Memulihkan draft lokal.");
      return;
    }
    
    // Add columns with precise pricing structures
    let tempStr = "nama,kode,hargaBeli,hargaJual,stok,wholesale1Min,wholesale1Harga,wholesale2Min,wholesale2Harga,kategori\n";
    barang.forEach(p => {
      if (!p) return;
      const namaAman = p.nama || "Tanpa Nama";
      const sanitizedName = namaAman.replace(/,/g, ' '); // avoid separator collision
      tempStr += `${sanitizedName},${p.kode || ''},${p.beli || 0},${p.jual || 0},${p.stok || 0},${p.g1Min || 0},${p.g1Harga || 0},${p.g2Min || 0},${p.g2Harga || 0},${p.kategori || 'Lain-lain'}\n`;
    });

    const filename = `SRC_MASNGUD_Stok_${new Date().toISOString().slice(0, 10)}.csv`;
    const res = await exportAndSaveFile({
      filename,
      content: tempStr,
      mimeType: 'text/csv;charset=utf-8;',
      title: 'Katalog Stok SRC MASNGUD',
      description: 'Ekspor data stok barang SRC MASNGUD'
    });
    showToast(res.message);
  };

  // --- BULK OPERATIONS FOR STOCKS ---
  const handleBulkDelete = async () => {
    if (selectedGudangIds.length === 0) return;
    const confirmed = await showCustomConfirm(`Apakah Anda yakin ingin menghapus ${selectedGudangIds.length} barang terpilih secara masal?`);
    if (!confirmed) return;

    const itemsToDelete = barang.filter(p => selectedGudangIds.includes(p.id));
    const nextList = barang.filter(p => !selectedGudangIds.includes(p.id));
    registerDeletions('barang', selectedGudangIds);
    saveBarang(nextList);

    itemsToDelete.forEach(item => {
      addMutasiLog(
        item.id,
        item.nama,
        'hapus',
        item.stok,
        0,
        -item.stok,
        `Hapus masal (Bulk Delete)`
      );
    });

    const count = selectedGudangIds.length;
    setSelectedGudangIds([]);
    showToast(`🗑️ Berhasil menghapus ${count} barang terpilih secara masal.`);
  };

  const handleBulkCategory = (newCat: string) => {
    if (selectedGudangIds.length === 0) return;
    const nextList = barang.map(p => {
      if (selectedGudangIds.includes(p.id)) {
        return { ...p, kategori: newCat };
      }
      return p;
    });
    saveBarang(nextList);
    
    // Log mutasi
    selectedGudangIds.forEach(id => {
      const item = barang.find(x => x.id === id);
      if (item) {
        addMutasiLog(
          item.id,
          item.nama,
          'edit',
          item.stok,
          item.stok,
          0,
          `Ubah kategori masal ke: ${newCat}`
        );
      }
    });

    const count = selectedGudangIds.length;
    setSelectedGudangIds([]);
    showToast(`📁 Berhasil mengubah kategori ${count} barang ke ${newCat}!`);
  };

  const handleBulkPriceUpdate = (amount: number, mode: 'jual' | 'beli' | 'jual_fixed') => {
    if (selectedGudangIds.length === 0) return;
    
    const nextList = barang.map(p => {
      if (selectedGudangIds.includes(p.id)) {
        let newJual = p.jual;
        let newBeli = p.beli;
        if (mode === 'jual') {
          newJual = Math.round(p.jual * (1 + amount));
        } else if (mode === 'beli') {
          newBeli = Math.round(p.beli * (1 + amount));
        } else if (mode === 'jual_fixed') {
          newJual = Math.max(0, p.jual + amount);
        }
        return {
          ...p,
          jual: newJual,
          beli: newBeli
        };
      }
      return p;
    });
    
    saveBarang(nextList);
    
    // Log mutasi for each updated item
    selectedGudangIds.forEach(id => {
      const item = barang.find(x => x.id === id);
      if (item) {
        addMutasiLog(
          item.id,
          item.nama,
          'edit',
          item.stok,
          item.stok,
          0,
          `Penyesuaian masal harga (${mode}): amount ${amount}`
        );
      }
    });

    const count = selectedGudangIds.length;
    setSelectedGudangIds([]);
    showToast(`💰 Berhasil memperbarui harga untuk ${count} barang terpilih!`);
  };

  const handleSortClick = (field: 'nama' | 'stok' | 'jual' | 'beli' | 'margin' | 'expired') => {
    const nextOrder = sortGudangField === field 
      ? (sortGudangOrder === 'asc' ? 'desc' : 'asc')
      : (field === 'nama' || field === 'expired' ? 'asc' : 'desc');
    
    setSortGudangField(field);
    setSortGudangOrder(nextOrder);
    
    const fieldNames: Record<string, string> = {
      nama: 'Nama Barang',
      stok: 'Jumlah Stok',
      jual: 'Harga Jual',
      beli: 'Harga Beli',
      margin: 'Margin Laba',
      expired: 'Tanggal Kedaluwarsa'
    };
    showToast(`🔄 Diurutkan berdasarkan: ${fieldNames[field]} (${nextOrder === 'asc' ? 'Terkecil/A-Z' : 'Terbesar/Z-A'})`);
  };

  const handleBulkExportCSV = async () => {
    if (selectedGudangIds.length === 0) return;
    const itemsToExport = barang.filter(p => p && selectedGudangIds.includes(p.id));
    if (itemsToExport.length === 0) return;

    let tempStr = "nama,kode,hargaBeli,hargaJual,stok,wholesale1Min,wholesale1Harga,wholesale2Min,wholesale2Harga,kategori,rak,supplier\n";
    itemsToExport.forEach(p => {
      const namaAman = p.nama || "Tanpa Nama";
      const sanitizedName = namaAman.replace(/,/g, ' '); // avoid separator collision
      const rakAman = (p.rak || '').replace(/,/g, ' ');
      const supplierAman = (p.supplier || '').replace(/,/g, ' ');
      tempStr += `${sanitizedName},${p.kode || ''},${p.beli || 0},${p.jual || 0},${p.stok || 0},${p.g1Min || 0},${p.g1Harga || 0},${p.g2Min || 0},${p.g2Harga || 0},${p.kategori || 'Lain-lain'},${rakAman},${supplierAman}\n`;
    });

    const filename = `SRC_MASNGUD_BulkStok_${new Date().toISOString().slice(0, 10)}.csv`;
    const res = await exportAndSaveFile({
      filename,
      content: tempStr,
      mimeType: 'text/csv;charset=utf-8;',
      title: 'Stok Terpilih SRC MASNGUD',
      description: `Ekspor ${itemsToExport.length} barang terpilih`
    });
    showToast(res.message);
  };

  const handleImportCSVChange = (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const fileReader = new FileReader();
    fileReader.onload = async () => {
      const text = fileReader.result as string;
      const lines = text.split(/\r?\n/);
      if (lines.length <= 1) {
        await showCustomAlert("Berkas CSV kosong atau tidak memiliki tajuk.");
        return;
      }

      let countSuccess = 0;
      const parsedStock: ItemBarang[] = [...barang];

      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        const cols = line.split(',');
        if (cols.length >= 5) {
          const rawName = cols[0].trim();
          const rawBarcode = cols[1].trim().replace(/['"‘“]/g, ''); // strip single/double ticks
          const rawBeli = parseFloat(cols[2]) || 0;
          const rawJual = parseFloat(cols[3]) || 0;
          const rawStok = parseInt(cols[4], 10) || 0;
          
          const rawG1Min = parseInt(cols[5], 10) || 0;
          const rawG1Harga = parseFloat(cols[6]) || 0;
          const rawG2Min = parseInt(cols[7], 10) || 0;
          const rawG2Harga = parseFloat(cols[8]) || 0;

          let rawKategori: 'Minuman' | 'Makanan' | 'Perawatan' | 'Rokok' | 'Lain-lain' = 'Lain-lain';
          if (cols.length >= 10 && cols[9]) {
            const val = cols[9].trim();
            if (['Minuman', 'Makanan', 'Perawatan', 'Rokok', 'Lain-lain'].includes(val)) {
              rawKategori = val as any;
            }
          }

          if (!rawBarcode || !rawName) continue;

          const existingIndex = parsedStock.findIndex(p => p.kode === rawBarcode);
          if (existingIndex !== -1) {
            // Merge / Overwrite properties
            parsedStock[existingIndex] = {
              ...parsedStock[existingIndex],
              nama: rawName,
              beli: rawBeli,
              jual: rawJual,
              stok: rawStok,
              g1Min: rawG1Min,
              g1Harga: rawG1Harga,
              g2Min: rawG2Min,
              g2Harga: rawG2Harga,
              kategori: rawKategori
            };
          } else {
            // Insert brand new product
            parsedStock.push({
              id: `prod-csv-${Date.now()}-${i}`,
              nama: rawName,
              kode: rawBarcode,
              beli: rawBeli,
              jual: rawJual,
              stok: rawStok,
              g1Min: rawG1Min,
              g1Harga: rawG1Harga,
              g2Min: rawG2Min,
              g2Harga: rawG2Harga,
              kategori: rawKategori
            });
          }
          countSuccess++;
        }
      }

      saveBarang(parsedStock);
      showToast(`✅ CSV Berhasil diimpor. ${countSuccess} produk diproses!`);
      e.target.value = ''; // clear input field
    };

    fileReader.readAsText(file);
  };

  // --- POS DATABASE INSTANT BACKUP & RECOVERY SUITE ---
