  // --- OPTIMASI MEMORI & ARSIP TRANSAKSI LAMA (PREVENTS LAG / HEAVY STORAGE) ---
  const handleArchiveOldTransactions = async (days: number = archiveDays) => {
    try {
      if (transaksi.length === 0) {
        showToast('ℹ️ Tidak ada transaksi untuk diarsipkan.');
        return;
      }

      const cutoffDate = new Date();
      cutoffDate.setDate(cutoffDate.getDate() - days);
      cutoffDate.setHours(0, 0, 0, 0);

      const oldTransactions = transaksi.filter(t => {
        const d = parseTransactionDate(t);
        return d < cutoffDate;
      });

      if (oldTransactions.length === 0) {
        showToast(`ℹ️ Tidak ada transaksi yang lebih lama dari ${days} hari.`);
        return;
      }

      const confirmed = window.confirm(
        `📦 KONFIRMASI PENGARSIPAN MEMORI KASIR\n\n` +
        `Ditemukan ${oldTransactions.length} transaksi lampau (> ${days} hari lalu).\n\n` +
        `• Sistem akan mengunduh file cadangan arsip (.json) otomatis terlebih dahulu.\n` +
        `• Transaksi lama akan dibersihkan dari RAM kasir agar transaksi kembali ringan, responsif, dan bebas lag.\n\n` +
        `Lanjutkan pengarsipan & optimasi sekarang?`
      );

      if (!confirmed) return;

      setIsOptimizingStorage(true);

      const d = new Date();
      const dateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
      const filename = `SRC_MASNGUD_ARSIP_TRANSAKSI_${days}HARI_${dateStr}.json`;

      const archiveData = {
        app: "SRC_MASNGUD_POS_ARCHIVE",
        keterangan: `Arsip Transaksi Lampau Lebih Dari ${days} Hari`,
        tanggalArsip: new Date().toISOString(),
        totalArsip: oldTransactions.length,
        transaksi: oldTransactions
      };

      await exportAndSaveFile({
        filename,
        content: JSON.stringify(archiveData, null, 2),
        mimeType: 'application/json;charset=utf-8;',
        title: `Arsip Transaksi POS (${days} Hari)`,
        description: `Cadangan arsip transaksi lama SRC MASNGUD (${oldTransactions.length} nota)`
      });

      // Keep only recent transactions
      const remainingTransactions = transaksi.filter(t => {
        const d = parseTransactionDate(t);
        return d >= cutoffDate;
      });

      setTransaksi(remainingTransactions);
      safeLocalStorageSet('src_transaksi', JSON.stringify(remainingTransactions));

      // Clean temporary storage
      const keysToClean = ['src_temp_preview', 'src_audit_cache', 'src_pdf_temp', 'src_cached_stats', 'src_temp_img'];
      keysToClean.forEach(k => {
        try { localStorage.removeItem(k); } catch (_) {}
      });

      showToast(`✅ Berhasil! ${oldTransactions.length} transaksi lampau telah diarsipkan & memori kasir kini kembali enteng!`);
    } catch (err: any) {
      console.error("Gagal mengarsipkan transaksi:", err);
      showToast("❌ Gagal mengarsipkan transaksi: " + (err?.message || String(err)));
    } finally {
      setIsOptimizingStorage(false);
    }
  };

  const handleCleanStorageCaches = () => {
    try {
      const keysToClean = ['src_temp_preview', 'src_audit_cache', 'src_pdf_temp', 'src_cached_stats', 'src_temp_img', 'src_parked_carts'];
      let cleaned = 0;
      keysToClean.forEach(k => {
        if (localStorage.getItem(k)) {
          localStorage.removeItem(k);
          cleaned++;
        }
      });
      showToast(`✨ Pembersihan cache memori berhasil (${cleaned} item sementara dibebaskan).`);
    } catch (e: any) {
      showToast("Gagal membersihkan cache: " + e?.message);
    }
  };

  const handleImportPelangganCSV = (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const text = event.target?.result as string;
        const lines = text.split(/\r?\n/);
        if (lines.length <= 1) {
          await showCustomAlert("Berkas CSV kosong atau tidak valid.");
          return;
        }

        // CSV parsing helper taking care of quotes
        const parseCSVLine = (line: string) => {
          const result: string[] = [];
          let current = '';
          let inQuotes = false;
          for (let i = 0; i < line.length; i++) {
            const char = line[i];
            if (char === '"') {
              if (inQuotes && line[i + 1] === '"') {
                current += '"';
                i++;
              } else {
                inQuotes = !inQuotes;
              }
            } else if (char === ',' && !inQuotes) {
              result.push(current.trim());
              current = '';
            } else {
              current += char;
            }
          }
          result.push(current.trim());
          return result;
        };

        const newPelangganList = [...pelanggan];
        let importCount = 0;
        let updateCount = 0;

        for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;
          
          const columns = parseCSVLine(line);
          if (columns.length < 2) continue; // must have at least ID and Name

          const [id, nama, telepon, tanggalDaftar, poin, totalBelanja, catatan] = columns;
          if (!nama) continue;

          const targetId = id || `pel-${Date.now().toString().slice(-6)}-${i}`;
          const existingIdx = newPelangganList.findIndex(p => p.id === targetId);

          const item: Pelanggan = {
            id: targetId,
            nama: nama,
            telepon: telepon || "-",
            tanggalDaftar: tanggalDaftar || new Date().toLocaleDateString('id-ID', { year: 'numeric', month: '2-digit', day: '2-digit' }),
            poin: Number(poin) || 0,
            totalBelanja: Number(totalBelanja) || 0,
            catatan: catatan || ""
          };

          if (existingIdx > -1) {
            newPelangganList[existingIdx] = item;
            updateCount++;
          } else {
            newPelangganList.push(item);
            importCount++;
          }
        }

        savePelanggan(newPelangganList);
        showToast(`✅ Pelanggan diimpor! ${importCount} member baru, ${updateCount} profil diperbarui.`);
      } catch (err) {
        await showCustomAlert("Gagal mengurai database CSV Pelanggan: " + (err instanceof Error ? err.message : String(err)));
      }
    };
    reader.readAsText(file);
    e.target.value = ''; // Reset input
  };
  // --- PRINT MEMBER CARD VIA WEB USB/WIFI & PHYSICAL BLUETOOTH THERMAL ---
